pub enum Msg {
    Ping,
    Hello(String),
}

pub const PROTOCOL_VERSION: u8 = 1;

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(hello) = bytes.strip_prefix("v:2:hello:") {
        return Ok(Msg::Hello(hello.into()));
    }

    match bytes {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        _ => Err("unknown".into()),
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => format!("v{}:ping", PROTOCOL_VERSION),
        Msg::Hello(hello) => format!("v:2:hello:{hello}"),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    fn assert_ping_encode_roundtrip() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn encodes_and_decodes_ping() {
        assert_ping_encode_roundtrip();
    }

    #[test]
    fn encodes_the_current_ping_version() {
        assert_eq!(encode(&Msg::Ping), "v1:ping");
    }

    #[test]
    fn decodes_both_supported_ping_forms() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
        assert!(matches!(decode("v1:ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn encodes_hello_with_the_v2_envelope() {
        assert_eq!(encode(&Msg::Hello("world".into())), "v:2:hello:world");
    }

    #[test]
    fn roundtrips_hello() {
        let message = Msg::Hello("world".into());
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Hello(text)) if text == "world"));
    }
}
